function autosize(){document.querySelectorAll('textarea.stem,textarea.instructions').forEach(t=>{t.style.height='auto';t.style.height=t.scrollHeight+'px';});}
function refreshInline(){const e=exam();const outlineHTML=sideHTML();if($('.side-content')._markup!==outlineHTML){$('.side-content').innerHTML=outlineHTML;$('.side-content')._markup=outlineHTML;}refreshReferenceScope(mvpContext);refreshWorkbench();refreshStudio();if($('.breadcrumb b'))$('.breadcrumb b').textContent=e.title;if($('.header-title')&&document.activeElement!==$('.header-title'))$('.header-title').value=e.title;$('.main-footer span').textContent=e.questions.length+' câu · '+e.questions.filter(isApproved).length+' câu đã duyệt · Bản đề '+e.revision;for(const q of e.questions){const el=document.querySelector(`[data-q="${q.id}"] .q-status`);if(el){el.className='q-status '+statusClass(q);el.innerHTML=`<span class="dot ${statusClass(q)}"></span>${esc(statusText(q))}`;}}document.querySelectorAll('[data-action="undo"]').forEach(n=>n.disabled=!e.undo.length&&!hasPendingEditorChanges());document.querySelectorAll('[data-action="redo"]').forEach(n=>n.disabled=!e.redo.length);}
function sideHTML(){const e=exam();const ref=referenceSide(e,selected,tab);if(ref!==null)return ref;if(tab==='outline')return `<div class="section-label"><span>NỘI DUNG ĐỀ</span><span>${String(e.questions.length).padStart(2,'0')}</span></div>${e.questions.map((q,i)=>`<button class="outline-item ${selected===q.id?'active':''}" data-action="select" data-id="${q.id}"><span class="number">${String(i+1).padStart(2,'0')}</span><span style="flex:1"><span class="outline-title">${esc(q.stem||'Câu hỏi mới')}</span><span class="outline-sub">${esc(q.topic)} · ${LEVELS[q.level]}</span></span><span class="dot ${statusClass(q)}" title="${statusText(q)}"></span></button>`).join('')}${button('add-question',icon('plus')+'Thêm câu hỏi','wide ghost')}<div class="section-label" style="margin-top:27px">CÔNG CỤ</div>${button('quotes',icon('book')+'Đối chiếu đoạn trích','wide ghost')}${button('extract',icon('file')+'Rút trích đề thi','wide ghost')}${button('library',icon('folder')+'Đề đã lưu','wide ghost')}`;
 if(tab==='docs')return `<div class="section-label">TÀI LIỆU CỦA ĐỀ <span>${e.docs.length}</span></div>${e.docs.map(d=>`<div class="small-card">${icon('file')}<b>${esc(d.name)}</b><p>${d.sample?'Tư liệu tự soạn minh họa':d.pages?.some(p=>p.text)?'Đã đọc '+d.pages.length+' trang / slide':d.kind==='text'?'Văn bản đã nhập':'Bản gốc · cần rút trích'}</p>${button('source','Mở tài liệu','',`data-doc="${d.id}"`)}</div>`).join('')}${button('import-doc',icon('plus')+'Thêm tài liệu','wide')}${button('quotes','Tìm & đối chiếu đoạn trích','wide ghost')}<p class="hint">TXT/MD: đọc nội dung tại máy.<br>PDF/PPTX/DOCX: đọc văn bản tại máy.<br>Ảnh/scan: rút trích tiếng Việt/Anh.</p>`;
 const rows=matrix(e);return `<div class="section-label">CƠ CẤU ĐỀ</div><p class="hint">Thực có / yêu cầu</p><table class="matrix-mini"><tr><th>Chủ đề</th><th>NB</th><th>TH</th><th>VD</th></tr>${rows.map(r=>`<tr><td>${esc(r.topic)}</td>${r.cells.map(c=>`<td class="count ${c.actual===c.target?'match':'miss'}">${c.actual}/${c.target}</td>`).join('')}</tr>`).join('')}</table><p class="matrix-note">${e.matrixConfirmed?'Đã xác nhận cơ cấu':'Cơ cấu chưa được xác nhận'}. Mức nhận thức do người soạn gán, chưa được AI hay chuyên gia đánh giá.</p>${unmappedHTML()}${button('matrix',icon('grid')+'Điều chỉnh ma trận','wide')}${button('check-all',icon('check')+'Rà soát đề','wide ghost')}`;}
function unmappedHTML(){const e=exam();const count=e.questions.filter(q=>!e.matrix.some(r=>r.topic===q.topic)).length;return count?`<p class="unmapped">${count} câu thuộc chủ đề chưa có trong ma trận.</p>`:'';}
function dataHTML(){const e=exam();let diagram;try{diagram=dataChartSVG(e.data);}catch{diagram='<p role="alert">Dữ kiện chưa hợp lệ. Chọn Sửa dữ kiện để kiểm tra.</p>';}return `<div class="data-card"><div class="data-heading">Bảng 1. Số người sử dụng thư viện ${button('data',icon('edit')+'Sửa dữ kiện')}</div><p class="data-sub">Dữ liệu minh họa tự tạo · Đơn vị: người</p><div class="data-body"><table><tr><th>Khu vực</th><th class="num">Số người</th></tr>${e.data.map(d=>`<tr><td>${esc(d.label)}</td><td class="num">${esc(d.value)}</td></tr>`).join('')}</table>${diagram}</div></div>`;}
function answerInputs(q,i){
 if(q.type==='short')return `<input data-q-field="answerText" data-id="${q.id}" aria-label="Đáp án ngắn câu ${i+1}" value="${esc(q.answerText||'')}">`;
 if(q.type==='truefalse')return [0,1,2,3].map(j=>`<label>${j+1}. <select data-q-field="truthValue" data-index="${j}" data-id="${q.id}" aria-label="Nhận định ${j+1} câu ${i+1}"><option value="" ${q.answerKnown===false&&!q.truthValues?.some(x=>x===null)?'selected':''}>Chưa xác nhận</option>${[true,false].map(value=>`<option value="${value}" ${q.truthValues?.[j]===value&&(q.answerKnown!==false||q.truthValues?.some(x=>x===null))?'selected':''}>${value?'Đúng':'Sai'}</option>`).join('')}</select></label>`).join('');
 return `<select class="answer-select" aria-label="Đáp án câu ${i+1}" data-q-field="answer" data-id="${q.id}">${q.answerKnown===false?'<option value="" selected>Chưa xác nhận</option>':''}${q.options.map((_,j)=>`<option value="${j}" ${j===q.answer&&q.answerKnown!==false?'selected':''}>${String.fromCharCode(65+j)}</option>`).join('')}</select>`;
}
function questionHTML(q,i){return `<section class="question ${selected===q.id?'selected':''}" id="q-${q.id}" data-q="${q.id}"><div class="q-top"><b class="q-label">Câu ${i+1}.</b><div class="q-actions">${button('select','Chọn câu','',`data-id="${q.id}"`)}${button('question-meta',icon('settings'),'icon',`data-id="${q.id}" aria-label="Thông tin câu ${i+1}"`)}</div><span class="q-status ${statusClass(q)}"><span class="dot ${statusClass(q)}"></span>${statusText(q)==='Chưa thấy bất đồng trong phép tính'?'Phép tính chưa thấy bất đồng':statusText(q)}</span></div><textarea class="stem" rows="1" data-q-field="stem" data-id="${q.id}" aria-label="Nội dung câu ${i+1}">${esc(q.stem)}</textarea><div class="options">${q.options.map((o,j)=>`<div class="option"><span>${String.fromCharCode(65+j)}.</span><input data-q-field="option" data-index="${j}" data-id="${q.id}" aria-label="Phương án ${String.fromCharCode(65+j)} câu ${i+1}" value="${esc(o)}"></div>`).join('')}</div>${button('source',icon('link')+esc(q.source?.location||'Chưa gắn nguồn'),'source-link',`data-id="${q.id}"`)}${q.type==='essay'?button('rubric','Lời giải & thang điểm','essay-rubric-link',`data-id="${q.id}"`):''}${teacher&&q.type==='essay'?rubricHTML(q):teacher?`<div class="answer-area"><div class="row"><span>${q.answerKnown===false?'Chưa nhập đáp án (chọn lại để xác nhận):':'Đáp án lưu:'}</span>${answerInputs(q,i)}<span class="key">Câu v${q.v}</span></div><textarea data-q-field="explanation" data-id="${q.id}" aria-label="Giải thích câu ${i+1}" rows="2">${esc(q.explanation)}</textarea></div>`:''}</section>`;}
function rightHTML(){return referenceChat(exam());}
function selectQ(id,scroll=true){const q=qget(id);if(!q)return;selected=id;selection=null;document.querySelectorAll('.question').forEach(n=>n.classList.toggle('selected',n.dataset.q===id));document.querySelectorAll('.outline-item').forEach(n=>n.classList.toggle('active',n.dataset.id===id));if(scroll)document.getElementById('q-'+id)?.scrollIntoView({block:'center',behavior:'smooth'});sidebarOpen=false;document.querySelector('.sidebar')?.classList.remove('open');}
function addChat(role,text){exam().chat.push({role,text,at:Date.now()});persist();}
function currentScope(){const q=qget(selected);if(!q)return null;if(selection?.id===q.id)return clone(selection);return questionScope(q);}
function showNew(){modal('Tạo đề mới',`<p class="hint">Chọn môn học. Thầy cô có thể nhập nội dung, dùng mẫu hoặc nhờ trợ lý soạn sau đó.</p><div class="new-subject-grid">${[['Toán','ƒ','Biểu thức và hình học'],['Vật lí','Ω','Công thức và đại lượng'],['Hoá học','H₂','Chất và phản ứng'],['Sinh học','Aa','Di truyền và tế bào'],['Ngữ văn','“','Ngữ liệu và câu hỏi'],['Tiếng Anh','En','Reading và bài tập']].map(([name,symbol,hint])=>`<button type="button" data-action="design-new-subject" data-subject="${name}" aria-pressed="${exam().subject===name}"><span>${symbol}</span><b>${name}</b><small>${hint}</small></button>`).join('')}</div><label for="new-subject">Môn học (có thể nhập môn khác)</label><input id="new-subject" value="${esc(exam().subject)}" maxlength="80"><p class="hint">Các yêu cầu soạn đề đã lưu sẽ được áp dụng cho đề mới.</p><details class="new-examples"><summary>Hoặc mở đề minh họa có sẵn</summary><div class="buttons">${button('essay-sample','Toán · 5 bài tự luận')}${button('create-sample','Địa lí · Bảng số liệu','','data-subject="Địa lí"')}${button('create-sample','Ngữ văn · Đọc hiểu','','data-subject="Ngữ văn"')}</div></details>${foot(button('create-blank',icon('plus')+'Tạo đề mới','primary'))}`);}

function createExam(subject,isSample){tab='outline';const e=isSample?sample(subject,state.prefs):blank(subject,state.prefs);if(isSample)e.questions.forEach(q=>check(e,q));state.exams.push(e);state.current=e.id;selected=null;selection=null;teacher=false;dialog.close();persist();render();toast('Đã tạo đề riêng · '+e.appliedPrefs.length+' yêu cầu được áp dụng');}
function showLibrary(){modal('Đề của tôi',`${state.exams.map(e=>`<div class="small-card library-meta"><div><b>${esc(e.title)}</b><p>${esc(e.subject)} · ${e.questions.length} câu · ${date(e.updated)}${e.sample?' · Mẫu':''}</p></div><div class="buttons">${button('open-exam',e.id===state.current?'Đang mở':'Mở đề',e.id===state.current?'ghost':'',`data-id="${e.id}"`)}${button('delete-exam',icon('trash'),'icon danger',`data-id="${e.id}" aria-label="Xóa đề ${esc(e.title)}"`)}</div></div>`).join('')}<p class="hint">Đề và hội thoại được lưu trong trình duyệt này. Xuất bản sao JSON để giữ một bản ngoài trình duyệt.</p>${foot(button('import-backup','Nhập bản sao JSON')+button('backup','Tải bản sao toàn bộ')+button('new','Tạo đề mới','primary'))}`);}
function readMatrixFormRows(form){const rows=[...form.querySelectorAll('[data-matrix-row]')].map(r=>({topic:r.querySelector('.topic').value.trim(),type:r.querySelector('[name=matrix-type]').value,...(r.querySelector('[name=matrix-points]').value?{pointsQ4:Number(r.querySelector('[name=matrix-points]').value)*4}:{}),targets:[...r.querySelectorAll('[data-matrix-target]')].map(n=>Number(n.value)),...(r.querySelector('[name=matrix-level-points]')?{pointsByLevelQ4:[...r.querySelectorAll('[name=matrix-level-points]')].map(n=>n.value?Number(n.value)*4:null)}:{})}));validateMatrixRows(rows);return rows;}
function mountMatrixTemplates(e){
 const panel=document.getElementById('matrix-templates-panel'),list=document.getElementById('matrix-templates-list'),saveBtn=document.getElementById('matrix-template-save'),nameInput=document.getElementById('matrix-template-name');
 if(!panel||!list)return;
 const renderList=async()=>{
  const response=await fetch('/api/matrix-templates',{headers:db.workspaceHeaders()}).catch(()=>null);
  if(!response||response.status===404){panel.hidden=true;return;}
  if(!response.ok){list.innerHTML='<p class="hint">Chưa tải được mẫu ma trận cá nhân.</p>';return;}
  const {templates=[]}=await response.json();
  if(!templates.length){list.innerHTML='<p class="hint">Chưa có mẫu ma trận đã lưu.</p>';return;}
  list.innerHTML=templates.map(t=>`<div class="small-card library-meta" data-template-id="${esc(t.id)}"><div><b>${esc(t.name)}</b><p>${esc(t.subject)} · Lớp ${esc(t.grade)} · ${t.total_questions} câu</p></div><div class="buttons"><button type="button" data-apply-template="${esc(t.id)}">Áp dụng mẫu</button><button type="button" class="danger" data-delete-template="${esc(t.id)}">Xóa</button></div></div>`).join('');
  list.querySelectorAll('[data-apply-template]').forEach(btn=>btn.onclick=()=>{
   const tpl=templates.find(item=>item.id===btn.dataset.applyTemplate);if(!tpl)return;
   validateMatrixRows(tpl.rows);
   change('Áp dụng mẫu ma trận cá nhân (chưa xác nhận)',target=>{target.matrix=clone(tpl.rows);target.matrixConfirmed=false;});
   showMatrix();toast('Đã nạp mẫu “'+tpl.name+'”. Hãy kiểm và xác nhận trước khi sinh.');
  });
  list.querySelectorAll('[data-delete-template]').forEach(btn=>btn.onclick=async()=>{
   const res=await fetch('/api/matrix-templates/'+encodeURIComponent(btn.dataset.deleteTemplate),{method:'DELETE',headers:db.workspaceHeaders()});
   if(!res.ok)throw Error('Chưa xóa được mẫu ma trận.');
   await renderList();toast('Đã xóa mẫu ma trận.');
  });
 };
 saveBtn.onclick=async()=>{
  try{
   const rows=readMatrixFormRows(document.getElementById('matrix-form'));
   const name=(nameInput.value||'').trim()||`${e.subject} ${e.grade} · ${rows.length} chủ đề`;
   const res=await fetch('/api/matrix-templates',{method:'POST',headers:{'Content-Type':'application/json',...db.workspaceHeaders()},body:JSON.stringify({name,subject:e.subject||'Chưa rõ môn',grade:String(e.grade||'10'),rows})});
   if(!res.ok){const err=await res.json().catch(()=>({}));throw Error(err.detail?.[0]?.msg||err.error||'Chưa lưu được mẫu ma trận.');}
   nameInput.value='';await renderList();toast('Đã lưu mẫu ma trận cá nhân.');
  }catch(error){toast(error.message);}
 };
 void renderList().catch(err=>{list.innerHTML='<p class="hint">'+esc(err.message)+'</p>';});
}
function showMatrix(){const e=exam();modal('Ma trận đề',`<p class="hint">Mỗi ô có số câu thực tế và số câu yêu cầu. Nhãn mức nhận thức do thầy cô gán; chưa đánh giá nội dung bằng AI.</p><form id="matrix-form"><table class="matrix-full"><thead><tr><th>Chủ đề</th><th>Loại câu</th><th>Điểm/câu</th>${LEVELS.map(l=>`<th>${l}</th>`).join('')}<th></th></tr></thead><tbody id="matrix-rows">${matrix(e).map((r,i)=>matrixRow(r.topic,r.targets,r.cells.map(c=>c.actual),i,r)).join('')}</tbody></table>${button('matrix-add',icon('plus')+'Thêm chủ đề','ghost','type="button"')}<div class="matrix-total">Thực có: ${e.questions.length} câu · Yêu cầu: ${e.matrix.flatMap(r=>r.targets).reduce((a,b)=>a+b,0)} câu</div>${unmappedHTML()}<p class="hint">NB = Nhận biết · TH = Thông hiểu · VD = Vận dụng. Mức nhận thức không đồng nhất với độ khó thực nghiệm.</p><label><input type="checkbox" id="matrix-confirm" ${e.matrixConfirmed?'checked':''} style="width:auto"> Tôi xác nhận cơ cấu này</label>${foot('<button class="primary" type="submit">Lưu ma trận</button>')}</form><div class="toolbar-row">${button('matrix-import','Nhập ma trận JSON')}${button('matrix-export','Tải ma trận JSON')}<button type="button" id="open-matrix-synthesis">Sinh theo ma trận · Python</button></div><details id="matrix-templates-panel"><summary>Mẫu ma trận cá nhân tái sử dụng</summary><div class="matrix-template-save-row"><input id="matrix-template-name" maxlength="160" placeholder="Ví dụ: Giữa kỳ I Toán 9 · Chuẩn 10đ" aria-label="Tên mẫu ma trận"><button type="button" id="matrix-template-save">Lưu mẫu hiện tại</button></div><div id="matrix-templates-list" class="matrix-templates-list"><p class="hint">Đang tải mẫu đã lưu…</p></div></details><small class="hint">JSON: [{"topic":"Chủ đề","targets":[2,1,1]}]. Nhập xong vẫn cần xem và xác nhận.</small>`);document.getElementById('open-matrix-synthesis').onclick=()=>openMatrixSynthesis(mvpContext).catch(error=>toast(error.message));mountMatrixTemplates(e);}
function matrixRow(topic,targets,counts,i,row={}){return `<tr data-matrix-row="${i}"><td><input class="topic" aria-label="Chủ đề ${i+1}" value="${esc(topic)}" maxlength="80" required></td><td><select name="matrix-type" aria-label="Loại câu chủ đề ${i+1}">${Object.entries(QUESTION_TYPES).map(([key,label])=>`<option value="${key}" ${(row.type||'mcq')===key?'selected':''}>${label}</option>`).join('')}</select></td><td><input name="matrix-points" aria-label="Điểm mỗi câu chủ đề ${i+1}" type="number" min="0.25" max="10" step="0.25" placeholder="Tự chia" value="${row.pointsQ4==null?'':row.pointsQ4/4}" ${row.pointsByLevelQ4?'disabled':''}></td>${LEVELS.map((_,l)=>`<td><div class="hint">Có ${counts[l]}</div><input aria-label="${LEVELS[l]} chủ đề ${i+1}" data-matrix-target type="number" min="0" max="30" value="${targets[l]||0}" required>${row.pointsByLevelQ4?`<label class="hint">Điểm/câu<input name="matrix-level-points" type="number" min="0.25" max="10" step="0.25" value="${row.pointsByLevelQ4[l]==null?'':row.pointsByLevelQ4[l]/4}"></label>`:''}</td>`).join('')}<td>${button('matrix-remove',icon('trash'),'icon ghost','type="button" aria-label="Xóa dòng ma trận"')}</td></tr>`;}
function showMetadata(){const e=exam();modal('Thông tin đề',`<form id="meta-form"><label>Tên đề</label><input name="title" value="${esc(e.title)}" required maxlength="180"><label>Đơn vị / trường</label><input name="school" value="${esc(e.school)}" required maxlength="180"><div class="grid3"><div><label>Môn</label><input name="subject" value="${esc(e.subject)}" required maxlength="80"></div><div><label>Lớp</label><input name="grade" value="${esc(e.grade)}" required maxlength="40"></div><div><label>Thời gian (phút)</label><input name="minutes" type="number" min="1" max="300" value="${e.minutes}" required></div></div><label>Hướng dẫn làm bài</label><textarea name="instructions" rows="3">${esc(e.instructions)}</textarea>${foot('<button type="submit" class="primary">Lưu thông tin</button>')}</form>`);}
function showQuestionMeta(id){const e=exam(),q=qget(id);if(!q)return;modal('Thông tin câu '+(e.questions.indexOf(q)+1),`<form id="q-meta-form" data-id="${q.id}"><div class="grid2"><div><label>Chủ đề</label><input name="topic" value="${esc(q.topic)}" list="topics" required maxlength="80"><datalist id="topics">${e.matrix.map(r=>`<option>${esc(r.topic)}</option>`).join('')}</datalist></div><div><label>Mức nhận thức (thầy cô gán)</label><select name="level">${LEVELS.map((l,i)=>`<option value="${i}" ${i===q.level?'selected':''}>${l}</option>`).join('')}</select></div></div><label>Tài liệu căn cứ</label><select name="docId"><option value="">Chưa gắn nguồn</option>${e.docs.map(d=>`<option value="${d.id}" ${q.source?.docId===d.id?'selected':''}>${esc(d.name)}</option>`).join('')}</select><label>Vị trí trong nguồn (thầy cô nhập)</label><input name="location" value="${esc(q.source?.location||'')}" maxlength="180"><label>Loại câu hỏi</label><select name="type">${Object.entries(QUESTION_TYPES).map(([key,label])=>`<option value="${key}" ${q.type===key?'selected':''}>${label}</option>`).join('')}</select><label>Điểm</label><input name="points" type="number" min="0.25" max="10" step="0.25" value="${q.points||1}">${q.type==='mcq'?'<label>Đáp án lưu (trắc nghiệm)</label><select name="answer">':'<p class="hint">Sửa đáp án đúng–sai/ngắn ở tab Đáp án trên trang đề.</p>'}${q.type==='mcq'?`${q.answerKnown===false?'<option value="" selected>Chưa xác nhận</option>':''}${q.options.map((o,i)=>`<option value="${i}" ${q.answer===i&&q.answerKnown!==false?'selected':''}>${String.fromCharCode(65+i)}. ${esc(o)}</option>`).join('')}</select>`:''}<label>Giải thích</label><textarea name="explanation" rows="3">${esc(q.explanation)}</textarea><div class="hint">Liên kết do thầy cô chọn. App không tự xác nhận nguồn hỗ trợ nội dung câu hỏi.</div>${q.rule?.startsWith('math-')?'<div class="alert">Phép kiểm Toán chỉ hỗ trợ đúng dạng câu mẫu. Có thể đổi các số trong câu; dạng chưa hỗ trợ sẽ báo chưa giải lại nội dung. Không dùng AI.</div>':q.rule?'<div class="alert">Câu này dùng phép tính liên kết với Bảng 1. Sửa thân câu thủ công sẽ ngừng phép giải theo mẫu; bảng vẫn giữ liên kết dữ kiện.</div>':''}${foot(button('delete-question','Xóa câu','danger',`type="button" data-id="${q.id}"`)+button('move-up','↑ Đưa lên','',`type="button" data-id="${q.id}" ${e.questions.indexOf(q)===0?'disabled':''}`)+button('move-down','↓ Đưa xuống','',`type="button" data-id="${q.id}" ${e.questions.indexOf(q)===e.questions.length-1?'disabled':''}`)+'<button class="primary" type="submit">Lưu câu</button>')}</form>`);}
function showReplace(sampleMode=false){const s=currentScope();if(!s){toast('Thêm hoặc chọn một câu trước.');return;}if(s.field&&s.field!=='stem'){toast('Chọn thân câu để dùng lệnh thay đoạn. Có thể sửa lời giải hoặc phương án trực tiếp trên trang.');return;}const q=qget(s.id);pending={...s,type:'replace'};const suggestion=sampleMode?(q.rule==='math-square'?s.text.replace(/=\s*[−-]?\d+/, '= −9'):q.rule==='max'?'Khu vực nào có nhiều người sử dụng thư viện nhất theo Bảng 1?':q.rule==='difference'?'Theo Bảng 1, chênh lệch số người sử dụng thư viện giữa khu vực B và A là bao nhiêu?':s.text.replace(/^Theo tư liệu, /,'').replace(/^Ngữ liệu lấy bối cảnh ở đâu\?$/,'Câu chuyện diễn ra ở đâu?')):s.text;
 modal(sampleMode?'Thử gợi ý mẫu':'Sửa phần đã chọn',`<div class="scope"><small>CÂU ${exam().questions.indexOf(q)+1} · v${q.v} · ${s.start===0&&s.end===q.stem.length?'TOÀN BỘ THÂN CÂU':'ĐOẠN ĐƯỢC CHỌN'}</small><div class="read-formula">${richTextHTML(s.text)}</div></div>${sampleMode?'<div class="alert">Gợi ý dựng sẵn để thử luồng duyệt thay đổi. Đây không phải câu trả lời từ AI.</div>':'<p class="hint">Nhập nội dung thay thế. Thầy cô sẽ xem trước thay đổi trước khi áp dụng.</p>'}<label for="replacement">Nội dung thay thế</label><textarea id="replacement" rows="4">${esc(suggestion)}</textarea>${foot(button('preview-replace','Xem thay đổi','primary'))}`);}
function previewReplace(value){
 const scope=pending;
 if(scope?.type!=='replace')return;
 const q=qget(scope.id);
 if(scope.field&&scope.field!=='stem'){toast('Chọn thân câu để dùng lệnh thay đoạn.');return;}
 if(!q||q.v!==scope.version||q.stem.slice(scope.start,scope.end)!==scope.text){
  toast('Câu đã đổi phiên bản. Vui lòng chọn lại đoạn cần sửa.');return;
 }
 if(value===scope.text){toast('Nội dung chưa thay đổi.');return;}
 const next=q.stem.slice(0,scope.start)+value+q.stem.slice(scope.end);
 try{validateMath(next);}catch(error){toast('Công thức chưa hợp lệ trong thân câu mới. Kiểm tra cú pháp hoặc dấu đóng. '+error.message);return;}
 pending={...scope,next,examId:exam().id};
 modal('Xem thay đổi trước khi áp dụng',`<div class="diff manual-diff"><div class="diff-heading">TRƯỚC</div><del>${richTextHTML(q.stem)}</del><div class="diff-heading">SAU</div><ins>${richTextHTML(next)}</ins></div><div class="alert">Phạm vi: thân câu ${exam().questions.indexOf(q)+1}. Đáp án và giải thích được giữ để thầy cô rà soát; trạng thái duyệt cũ hết hiệu lực.${q.rule?.startsWith('math-')?' Phép kiểm Toán đọc lại dữ kiện từ thân câu nếu dạng mới được hỗ trợ.':q.rule?' Phép giải theo câu mẫu sẽ dừng sau khi đổi nội dung.':''} Các câu khác và ngữ liệu đã chọn không thay đổi.</div>${foot(button('apply-replace','Xác nhận thay đổi','primary'))}`);
}
function showData(){const e=exam();if(!e.data.length){modal('Dữ kiện của đề Toán','<p class="hint">Các dữ kiện nằm trực tiếp trong câu hỏi. Thầy cô sửa số ngay trên trang đề, ví dụ x² = 9 thành x² = −9. Phép kiểm đọc nội dung hiện tại cho các dạng được hỗ trợ.</p>');return;}modal('Dữ kiện dùng chung cho bảng & biểu đồ',`<p class="hint">Dữ liệu minh họa tự tạo, không phải khảo sát thực. Một lần cập nhật sẽ đổi bảng, cột biểu đồ và rà soát các câu đang liên kết.</p><form id="data-form" data-exam="${esc(e.id)}" data-revision="${e.revision}"><table><tr><th>Khu vực</th><th>Số người</th></tr>${e.data.map((d,i)=>`<tr><td>${esc(d.label)}</td><td><input class="data-value" aria-label="Số người ${esc(d.label)}" data-data-index="${i}" type="number" min="0" max="1000000" step="1" value="${d.value}" required></td></tr>`).join('')}</table><div class="alert">Đáp án không tự chốt theo số mới. App tính lại, báo bất đồng hoặc phương án chưa khớp; thầy cô xem đề xuất sửa rồi duyệt.</div>${foot('<button type="submit" class="primary">Xem ảnh hưởng</button>')}</form>`);}
function showDataPreview(values){const e=exam(),test=planDataUpdate(e,values);if(!test)return toast('Dữ kiện chưa thay đổi.');pending={type:'data',update:test,examId:e.id,revision:e.revision};modal('Xem ảnh hưởng khi đổi dữ kiện',`<div class="diff"><del>${e.data.map(d=>`${esc(d.label)}: ${d.value}`).join(' · ')}</del><ins>${test.data.map(d=>`${esc(d.label)}: ${d.value}`).join(' · ')}</ins></div><h3>Phần sẽ cập nhật</h3><p class="hint">Bảng 1, biểu đồ cột và trạng thái các câu liên kết. Giữ nguyên nội dung các câu khác và đoạn trích đã duyệt.</p>${test.questions.filter(usesTable).map(q=>`<div class="small-card"><b>Câu ${test.questions.indexOf(q)+1} · ${statusText(q)}</b><p>${esc(q.check.evidence)}</p>${q.check.problems.length?`<p>${esc(q.check.problems.join(' '))}</p>`:''}</div>`).join('')}${foot(button('apply-data','Xác nhận cập nhật','primary'))}`);}
function runCheck(id){change('Kiểm tra câu '+(exam().questions.findIndex(q=>q.id===id)+1),e=>check(e,e.questions.find(q=>q.id===id)));showReview(id);}
function showReview(id){const e=exam(),q=qget(id);if(!q)return;const c=q.check?.version===q.v?q.check:null;const d=derive(e,q);modal('Rà soát câu '+(e.questions.indexOf(q)+1),`<div class="scope"><small>CÂU v${q.v}</small><div class="read-formula">${richTextHTML(q.stem)}</div></div>${c?`<div class="alert ${c.status==='review'?'':'success'}"><b>${statusText(q)}</b><br>${esc(c.problems.join(' ')||c.evidence)}</div><p class="hint">${esc(c.method||'Thầy cô tự duyệt')} · Lần kiểm tra ${date(c.at)} · Gắn với câu v${c.version}</p><h3>Căn cứ của phép kiểm</h3><p>${esc(c.evidence)}</p>`:'<div class="alert">Bản hiện tại chưa kiểm tra. Kết quả cũ không được dùng cho phiên bản mới.</div>'}${usesTable(q)?dataHTML():''}<div class="toolbar-row">${button('source',icon('link')+'Mở nguồn','',`data-id="${id}"`)}${button('check-one','Kiểm tra lại','',`data-id="${id}"`)}</div>${d&&(!d.error||d.result!==undefined)?`<div class="small-card"><b>Đề xuất sửa có căn cứ phép tính</b><p>${esc(d.explanation)}${d.answer===null?' Cần thay một phương án để chứa kết quả này.':''}</p>${button('repair-preview','Xem đề xuất sửa','',`data-id="${id}"`)}</div>`:''}<p class="hint">Phép kiểm này không đánh giá mọi khía cạnh kiến thức, cách diễn đạt hoặc mức nhận thức. Thầy cô quyết định bản dùng.</p>${foot(button('approve-question','Tôi đã rà soát · duyệt câu','primary',`data-id="${id}" data-version="${q.v}"`))}`);}
function showRepair(id){const e=exam(),q=qget(id),d=derive(e,q);if(!d||d.error&&d.result===undefined){toast('Cần sửa thủ công câu hoặc phương án trước.');return;}const options=clone(q.options);let answer=d.answer;if(answer===null){answer=0;options[0]=d.replacement??d.result+' người';}pending={type:'repair',id,version:q.v,answer,options,explanation:d.explanation};modal('Đề xuất sửa theo phép tính',`<p class="hint">Câu ${e.questions.indexOf(q)+1} · v${q.v}. Chỉ cập nhật đáp án, giải thích và phương án cần thiết của câu này.</p><div class="diff"><del>Đáp án: ${String.fromCharCode(65+q.answer)}\n${richTextHTML(q.explanation)}${d.answer===null?'\nA. '+richTextHTML(q.options[0]):''}</del><ins>Đáp án: ${String.fromCharCode(65+answer)}\n${richTextHTML(d.explanation)}${d.answer===null?'\nA. '+richTextHTML(options[0]):''}</ins></div><div class="alert">Sau khi áp dụng, app tính lại từ dữ kiện và lưu kết quả ở phiên bản mới. Thầy cô vẫn cần duyệt nội dung.</div>${foot(button('apply-repair','Áp dụng & kiểm tra lại','primary'))}`);}
async function showSource(docId,qid){const e=exam(),q=qget(qid);const doc=e.docs.find(d=>d.id===(docId||q?.source?.docId));if(!doc){modal('Nguồn của câu hỏi','<p class="hint">Chưa gắn tài liệu cho câu này. Thầy cô có thể thêm tài liệu và chọn nguồn trong thuộc tính câu.</p>'+foot(button('import-doc','Thêm tài liệu','primary')));return;}
 const original=doc.fileId?await db.get('file:'+doc.fileId):null;modal('Tài liệu căn cứ',`<h3>${esc(doc.name)}</h3><p class="hint">${esc(q?.source?.location||doc.location||'Toàn bộ tài liệu')}${doc.sample?' · Ngữ liệu minh họa do nhóm tự soạn':''}</p>${doc.kind==='text'?`<div class="source-preview">${esc(doc.text)}</div>`:original?`<div class="alert">Tệp gốc đã lưu tại máy. Chưa rút trích hoặc sinh câu bằng AI.</div>${doc.kind==='image'?`<img class="source-frame" src="${original}" alt="Bản gốc ${esc(doc.name)}">`:doc.kind==='pdf'?`<iframe class="source-frame" title="PDF gốc" src="${original}"></iframe>`:'<p class="hint">Trình xem slide chưa kết nối. Tải tệp gốc để mở bằng phần mềm trình chiếu.</p>'}`:'<div class="alert">Không tìm thấy tệp gốc trong trình duyệt này.</div>'}${original?foot(button('download-original','Tải tệp gốc','',`data-doc="${doc.id}"`)):''}${q?`<p class="hint">Liên kết nguồn giúp đối chiếu vị trí. App chưa xác minh nội dung câu hỏi dựa đủ vào nguồn này.</p>`:''}`);}
function showImport(){modal('Thêm tài liệu',`<p class="hint">Tài liệu được lưu tại trình duyệt này. Chưa gửi đi dịch vụ ngoài.</p><div class="upload-zone"><label for="doc-file">Chọn tệp TXT, MD, PDF, PPTX hoặc ảnh</label><input id="doc-file" type="file" accept=".txt,.md,.pdf,.pptx,.png,.jpg,.jpeg,.webp"><p class="hint">Tối đa 15 MB/tệp. TXT/MD đọc được ngay. PDF/PPTX/ảnh chỉ lưu bản gốc khi chưa có kết nối.</p></div><div class="alert">Chưa kết nối AI: app không sinh câu từ tệp vừa tải. Có thể đọc văn bản, thêm câu bằng tay và gắn nguồn.</div><h3>Hoặc dán nội dung</h3><form id="paste-doc-form"><label>Tên tài liệu</label><input name="name" placeholder="Ví dụ: Bài 3 — Đô thị hóa" required maxlength="180"><label>Nội dung tư liệu</label><textarea name="text" rows="6" required maxlength="1000000"></textarea>${foot('<button class="primary" type="submit">Lưu tư liệu tại máy</button>')}</form>`);}
function showMemory(){modal('Cách ra đề của thầy cô',`<p class="hint">Chỉ lưu những yêu cầu thầy cô xác nhận. Một lần sửa câu không tự trở thành sở thích lâu dài.</p>${state.prefs.length?state.prefs.map(p=>`<div class="preference-row"><div class="row"><span class="grow"><b>${esc(p.text)}</b><p class="hint" style="margin-bottom:0">${isConfirmedPreference(p)?'Đã xác nhận · áp dụng cho các đề tạo sau':'Chưa xác nhận · mở Sửa để xem lại'}</p></span>${button('edit-pref','Sửa','',`data-id="${p.id}"`)}${button('delete-pref',icon('trash'),'icon danger',`data-id="${p.id}" aria-label="Xóa yêu cầu"`)}</div></div>`).join(''):empty('Chưa có yêu cầu dùng lâu dài.')}<form id="pref-form"><label for="pref-text">Yêu cầu muốn dùng lại</label><textarea id="pref-text" rows="3" required placeholder="Ví dụ: Câu hỏi ngắn, tránh dùng phủ định kép." maxlength="500"></textarea><label>Cách áp dụng khi rà soát đề mới</label><select id="pref-kind"><option value="instruction">Lưu làm yêu cầu biên soạn</option><option value="short">Nhắc khi thân câu dài hơn 30 từ</option></select><label><input id="pref-confirm" type="checkbox" required style="width:auto"> Tôi xác nhận dùng yêu cầu này cho những đề sau</label>${foot('<button type="submit" class="primary">Xác nhận & ghi nhớ</button>')}</form><div class="alert success">Đề hiện tại đang áp dụng ${exam().appliedPrefs.filter(isConfirmedPreference).length} yêu cầu. Trợ lý dùng các yêu cầu đã xác nhận khi soạn theo ma trận. Quy tắc độ dài nhắc khi rà câu.</div>${foot(button('apply-prefs-current','Áp dụng danh sách hiện tại cho đề này'))}`);}
function showQuotes(){const e=exam();modal('Tìm nguồn & đối chiếu đoạn trích',`<div class="toolbar-row">${button('web-search','Tìm các bản trên web')}${button('add-variant','Thêm bản để đối chiếu')}</div><div class="alert">Có thể bấm tìm nguồn để truy vấn dịch vụ đã cấu hình. Các bản dưới đây là ${e.quote.versions.some(v=>v.external)?'nội dung nhập tay và ví dụ mẫu':'ví dụ tự soạn hoặc nội dung nhập tay'}, không phải kết quả vừa tìm trên mạng. Khác biệt không mặc nhiên là lỗi.</div><label>Đoạn đang dùng trong đề ${e.quote.chosen?'· đã được giáo viên chọn':''}</label><div class="source-preview">${esc(e.quote.text||'Chưa có đoạn trích')}</div><p class="hint">Các từ, dấu câu và xuống dòng khác so với đoạn đang dùng được tô vàng. Phần bị lược trong một bản sẽ thấy ở bản đối chiếu. Thầy cô quyết định bản phù hợp.</p><div class="grid2">${e.quote.versions.map(v=>`<div class="variant"><div class="row space"><b>${esc(v.label)}</b>${e.quote.chosen===v.id?'<span class="pill">Đang dùng</span>':''}</div><div class="version-text">${diffText(e.quote.text,v.text)}</div><p class="hint">${esc(v.location||'Người dùng nhập')} · ${v.webRetrieved?'Đã truy cập web, chưa xác minh bản chuẩn':v.external?'Nguồn do người dùng nhập, chưa xác minh':'Ngữ liệu tự soạn minh họa'}</p><div class="row">${v.docId?button('source','Mở nguồn','tiny-btn',`data-doc="${v.docId}" data-page="${Number.isInteger(v.page)&&v.page>0?v.page:1}"`):v.url?`<a href="${esc(v.url)}" target="_blank" rel="noopener noreferrer">Mở nguồn đã nhập</a>`:''}${button('choose-variant','Chọn bản này','tiny-btn',`data-id="${v.id}"`)}</div></div>`).join('')}</div>`);}
function diffText(a,b){const aa=a.match(/\s+|[\p{L}\p{N}]+|[^\s\p{L}\p{N}]/gu)||[],bb=b.match(/\s+|[\p{L}\p{N}]+|[^\s\p{L}\p{N}]/gu)||[];if(aa.length*bb.length>200000)return esc(b)+'<p class="hint">Văn bản dài: thu ngắn hai bản để tô khác biệt.</p>';const dp=Array.from({length:aa.length+1},()=>new Uint16Array(bb.length+1));for(let i=aa.length-1;i>=0;i--)for(let j=bb.length-1;j>=0;j--)dp[i][j]=aa[i]===bb[j]?1+dp[i+1][j+1]:Math.max(dp[i+1][j],dp[i][j+1]);const same=new Set();let i=0,j=0;while(i<aa.length&&j<bb.length){if(aa[i]===bb[j]){same.add(j);i++;j++;}else if(dp[i+1][j]>=dp[i][j+1])i++;else j++;}return bb.map((t,i)=>same.has(i)?esc(t):`<mark>${esc(t).replace(/\n/g,'↵<br>')}</mark>`).join('');}
function showAddVariant(){modal('Thêm bản đối chiếu',`<p class="hint">Dán bản thầy cô đã tìm được, ghi nguồn và vị trí. App chỉ đối chiếu văn bản; chưa xác minh tác giả hay độ tin cậy.</p><form id="variant-form"><label>Tên bản / ấn bản</label><input name="label" required maxlength="120"><label>Nội dung đoạn trích</label><textarea name="text" rows="7" required maxlength="6000"></textarea><label>Nguồn web (nếu có, https://…)</label><input name="url" type="url" placeholder="https://…"><label>Hoặc tài liệu đã nhập</label><select name="docId"><option value="">Không gắn tệp</option>${exam().docs.map(d=>`<option value="${d.id}">${esc(d.name)}</option>`).join('')}</select><label>Vị trí / ghi chú</label><input name="location" required maxlength="180">${foot('<button type="submit" class="primary">Thêm & đối chiếu</button>')}</form>`);}
function showHistory(){const e=exam();modal('Lịch sử của đề',`<p class="hint">Mỗi thay đổi lưu cả nội dung và phần phụ thuộc. Khôi phục tạo thêm một mốc lịch sử; vẫn có thể hoàn tác.</p>${e.history.length?[...e.history].reverse().slice(0,50).map(h=>`<div class="history-row"><b>${esc(h.label)}</b><small>${date(h.at)} · Bản đề ${h.revision} · ${h.state.questions.length} câu</small>${button('restore','Xem bản này','',`data-id="${h.id}"`)}</div>`).join(''):empty('Chưa có thay đổi. Hãy sửa một câu để tạo mốc lịch sử.')}`);}
function showExport(){modal('Xuất đề đang soạn',`<p class="hint">Bản xuất lấy trực tiếp từ nội dung hiện tại. Thầy cô có thể tải HTML, mở và chọn In / Lưu PDF trong trình duyệt.</p><div class="grid2"><div class="choice-card"><h3>Bản học sinh</h3><p>Câu hỏi, phương án, bảng và ngữ liệu. Không chứa đáp án, giải thích hoặc hội thoại.</p>${button('export-html','Tải bản học sinh','primary','data-teacher="false"')}${button('save-local','Lưu tệp tại máy','','data-teacher="false"')}${button('print','Xem / In','ghost','data-teacher="false"')}</div><div class="choice-card"><h3>Bản giáo viên</h3><p>Thêm đáp án lưu, giải thích, vị trí nguồn và trạng thái kiểm tra của từng câu.</p>${button('export-html','Tải bản giáo viên','','data-teacher="true"')}${button('save-local','Lưu tệp tại máy','','data-teacher="true"')}${button('print','Xem / In','ghost','data-teacher="true"')}</div></div><div class="alert">${exam().questions.filter(q=>statusClass(q)!=='approved').length} câu chưa được giáo viên duyệt. Bản xuất giữ nguyên trạng thái nội dung, không tự sửa đáp án.</div><p class="hint">Chưa hỗ trợ DOCX. HTML tải về là tệp HTML đúng định dạng. Lưu PDF qua hộp thoại in.</p>${foot(button('backup-local','Lưu bản sao JSON tại máy')+button('backup','Tải bản sao dữ liệu JSON'))}`);}
function showConnections(){modal('Kết nối & dữ liệu',`<div class="config-row"><div><strong>Soạn đề tại máy</strong><p>Sửa, lưu, ma trận, lịch sử, đối chiếu văn bản và xuất HTML.</p></div><span class="pill">Đang hoạt động</span></div>${[['Sinh & sửa câu bằng AI','Cần cấu hình máy chủ mô hình hoặc dịch vụ được cho phép.'],['Giải lại bằng AI theo phiên bản','Hiện chỉ có phép tính bảng và kiểm tra cấu trúc tại máy.'],['Rút trích PDF, slide và ảnh scan','Hiện lưu tệp gốc, đối chiếu và nhập văn bản bằng tay.'],['Tìm các bản trên web','Hiện đối chiếu các bản mẫu hoặc bản thầy cô dán vào.']].map(([t,d])=>`<div class="config-row"><div><strong>${t}</strong><p>${d}</p></div><span class="pill warn">Chưa kết nối</span></div>`).join('')}<p class="hint" style="margin-top:20px">App chỉ kết nối máy chủ tại máy để mở và lưu bản xuất, không gửi dữ liệu ra dịch vụ ngoài. Dữ liệu nằm trong IndexedDB của trình duyệt, theo địa chỉ mở app. Xóa dữ liệu trình duyệt sẽ xóa bản lưu tại đây; nên tải bản sao JSON.</p>`);}
async function showExtract(docId){const docs=exam().docs.filter(d=>d.kind==='image'||d.kind==='pdf');const d=docs.find(d=>d.id===docId)||docs[0];const original=d?.fileId?await db.get('file:'+d.fileId):null;modal('Rút trích đề thi',`<div class="alert">Chưa kết nối nhận dạng ảnh/scan. Thầy cô có thể đối chiếu bản gốc và gõ hoặc dán nội dung thủ công; app không báo đã nhận dạng.</div><div class="toolbar-row">${button('import-doc','Thêm ảnh / PDF gốc')}${docs.length?`<select id="scan-doc" aria-label="Chọn bản gốc">${docs.map(x=>`<option value="${x.id}" ${x.id===d?.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select>`:''}</div><div class="scan-layout"><div><h3>Bản gốc</h3>${original?d.kind==='image'?`<img class="source-frame" src="${original}" alt="Ảnh đề gốc">`:`<iframe class="source-frame" title="PDF đề gốc" src="${original}"></iframe>`:empty('Thêm ảnh hoặc PDF để đối chiếu tại đây.')}</div><div><h3>Văn bản nhập thủ công</h3><form id="scan-form" data-doc="${d?.id||''}"><textarea name="text" rows="12" required aria-label="Văn bản đối chiếu bản gốc" placeholder="Gõ lại nội dung tại đây. Dùng [chưa rõ: …] để đánh dấu chỗ cần xem bản gốc.">${esc(d?.manualText||'')}</textarea><p class="hint">Các chỗ [chưa rõ: …] được giữ trong tư liệu để thầy cô rà soát.</p><button class="primary" type="submit">Lưu bản nhập tay</button></form></div></div>`);}
function download(name,content,type){const a=document.createElement('a');const url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function safeName(s){return s.replace(/[<>:"/\\|?*\x00-\x1f]/g,'-').slice(0,100);}
async function backup(){flushEditor();await saveChain.catch(()=>{});const saved=clone(state),ids=new Set(),stack=[saved];while(stack.length){const item=stack.pop();if(!item||typeof item!=='object')continue;if(item.fileId)ids.add(item.fileId);stack.push(...Object.values(item).filter(v=>v&&typeof v==='object'));}const [files,curriculumSources,matrixTemplates]=await Promise.all([db.allFiles(ids),db.allPersonalLessons(),db.allMatrixTemplates()]);if([...ids].some(id=>!files[id]))throw Error('Chưa tải đủ tệp gốc (kể cả lịch sử/hoàn tác). Kết nối lại rồi sao lưu; chưa tạo bản thiếu tệp.');const data={format:'tro-ly-soan-de',version:1,savedAt:new Date().toISOString(),state:saved,files,...(curriculumSources?{curriculumSources}:{}),...(matrixTemplates?.length?{matrixTemplates}:{})},content=JSON.stringify(data,null,2);if(new Blob([content]).size>150*1024*1024)throw Error('Bản sao vượt150MB. Tách bớt tài liệu trước khi sao lưu.');download('Ban-sao-tro-ly-soan-de.json',content,'application/json');toast(curriculumSources===null?'Đã tải bản sao đề và tệp gốc. Kho học liệu cá nhân chưa có trong bản sao.':db.hasPendingWrites()?'Đã tải bản sao gồm cả nháp chưa đồng bộ':'Đã tải bản sao đề, tệp gốc và kho học liệu cá nhân.');}
async function saveLocal(payload){const response=await fetch('/api/save-export',{method:'POST',headers:{'Content-Type':'application/json',...db.workspaceHeaders()},body:JSON.stringify(payload)});if(!response.ok)throw Error(await response.text());const result=await response.json();modal('Tệp đã lưu tại máy',`<div class="alert success">Đã ghi tệp thật: ${esc(result.filename)} · ${result.bytes.toLocaleString('vi-VN')} byte</div><p class="hint">Tệp nằm trong thư mục exports cạnh mã app. Bản HTML có thể mở để in hoặc lưu PDF.</p><a class="saved-export-link" href="${esc(result.url)}" target="_blank" rel="noopener">Mở tệp vừa lưu</a>${foot(button('export','Quay lại xuất đề'))}`);}
function chooseFile(accept,callback){const input=document.createElement('input');input.type='file';input.accept=accept;input.onchange=()=>{if(input.files[0])Promise.resolve(callback(input.files[0])).catch(err=>toast(err.message));};input.click();}
async function importFile(file){if(file.size>15*1024*1024)throw Error('Tệp lớn hơn 15 MB. Chọn tệp nhỏ hơn.');const ext=file.name.split('.').pop().toLowerCase();if(!['txt','md','pdf','pptx','png','jpg','jpeg','webp'].includes(ext))throw Error('Định dạng chưa hỗ trợ.');const id=uid();let d={id,name:file.name,sample:false};if(['txt','md'].includes(ext)){d.kind='text';d.text=await file.text();}else{d.kind=ext==='pdf'?'pdf':ext==='pptx'?'slides':'image';d.fileId=uid();const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(Error('Không đọc được tệp'));r.readAsDataURL(file);});await db.put('file:'+d.fileId,data);}change('Thêm tài liệu '+d.name,e=>e.docs.push(d));tab='docs';render();await showSource(d.id);toast(d.kind==='text'?'Đã đọc nội dung văn bản tại máy':'Đã lưu tệp gốc · chưa rút trích nội dung');}
// Only declarative data is restored from backups. No HTML or code is executed.

const commitBeforeAction=new Set(['ai-check','approve-question','apply-block-patch','show-block-diff','undo','redo','view-student','view-teacher','export','export-html','print','save-local','backup','backup-local']);
async function handleAction(a,n){
 if(commitBeforeAction.has(a)&&!flushEditor()){toast('Gõ xong chữ đang nhập rồi thử lại.');return;}
 if(await handleStudioAction(a,n))return;if(await handleWorkbenchAction(a,n))return;if(await handleMVPAction(a,n))return;const e=exam();switch(a){
 case 'close':dialog.close();break;
 case 'new':showNew();break;
 case 'create-sample':createExam(n.dataset.subject,true);break;
 case 'create-blank':{const s=$('#new-subject').value.trim();if(!s)return toast('Nhập môn học.');createExam(s,false);break;}
 case 'library':showLibrary();break;
 case 'open-exam':state.current=n.dataset.id;selected=null;selection=null;dialog.close();persist();render();break;
 case 'delete-exam':{const target=state.exams.find(x=>x.id===n.dataset.id);modal('Xóa đề khỏi trình duyệt?',`<p>${esc(target.title)}</p><p class="hint">Có thể tải bản sao trước khi xóa.</p>${foot(button('backup','Tải bản sao')+button('confirm-delete-exam','Xóa đề','danger',`data-id="${target.id}"`))}`);break;}
 case 'confirm-delete-exam':state.exams=state.exams.filter(x=>x.id!==n.dataset.id);if(!state.exams.length)state.exams.push(blank('Lịch sử',state.prefs));if(!state.exams.some(x=>x.id===state.current))state.current=state.exams[0].id;persist();render();showLibrary();break;
 case 'tab':tab=n.dataset.tab;render();break;
 case 'select':selectQ(n.dataset.id);document.dispatchEvent(new CustomEvent('question-selected'));refreshInline();break;
 case 'toggle-chat':assistantOpen=!assistantOpen;$('.assistant').classList.toggle('open',assistantOpen);break;
 case 'toggle-left':sidebarOpen=!$('.sidebar').classList.contains('open');$('.sidebar').classList.toggle('open',sidebarOpen);break;
 case 'view-student':teacher=false;render();break;
 case 'view-teacher':teacher=true;render();break;
 case 'metadata':showMetadata();break;
 case 'question-meta':showQuestionMeta(n.dataset.id||selected);break;
 case 'add-question':{const q={id:uid(),v:1,stem:'Nhập nội dung câu hỏi…',options:['','','',''],answer:0,explanation:'',topic:e.matrix[0]?.topic||'Chủ đề mới',level:0,source:null,check:null};q.stem='Nhập nội dung câu hỏi…';change('Thêm câu hỏi',e=>{e.questions.push(q);check(e,q);});selectQ(q.id);break;}
 case 'delete-question':{const id=n.dataset.id;modal('Xóa câu hỏi?',`<p class="hint">Câu sẽ được bỏ khỏi trang đề và số đếm ma trận. Có thể hoàn tác.</p>${foot(button('confirm-delete-question','Xóa câu','danger',`data-id="${id}"`))}`);break;}
 case 'confirm-delete-question':change('Xóa câu hỏi',e=>{e.questions=e.questions.filter(q=>q.id!==n.dataset.id);});dialog.close();break;
 case 'move-up':case 'move-down':{const i=e.questions.findIndex(q=>q.id===n.dataset.id),j=i+(a==='move-up'?-1:1);if(j<0||j>=e.questions.length)return;change('Đổi thứ tự câu',e=>{[e.questions[i],e.questions[j]]=[e.questions[j],e.questions[i]];});showQuestionMeta(n.dataset.id);break;}
 case 'matrix':showMatrix();break;
 case 'matrix-add':$('#matrix-rows').insertAdjacentHTML('beforeend',matrixRow('',[0,0,0],[0,0,0],$('#matrix-rows').children.length));break;
 case 'matrix-remove':n.closest('tr').remove();break;
 case 'matrix-export':download('Ma-tran.json',JSON.stringify(e.matrix,null,2),'application/json');break;
 case 'matrix-import':chooseFile('.json',async f=>{const rows=JSON.parse(await f.text());validateMatrixRows(rows);change('Nhập ma trận (chưa xác nhận)',e=>{e.matrix=rows.map(r=>({topic:r.topic.trim(),targets:r.targets,...(r.type?{type:r.type}:{}),...(r.pointsQ4!=null?{pointsQ4:r.pointsQ4}:{})}));e.matrixConfirmed=false;});showMatrix();});break;
 case 'replace':showReplace();break;
 case 'sample-suggestion':if(!e.sample){toast('Gợi ý dựng sẵn chỉ dùng cho đề mẫu. Hãy sửa tay hoặc dùng “Đổi thành: …”.');return;}showReplace(true);break;
 case 'preview-replace':previewReplace($('#replacement').value);break;
 case 'apply-replace':{
  const p=pending;
  flushEditor();
  const q=qget(p?.id);
  if(p?.type!=='replace'||p.examId!==e.id||!q||q.v!==p.version||q.stem.slice(p.start,p.end)!==p.text){
   toast('Đề xuất đã cũ. Chọn lại câu để sửa.');break;
  }
  const rich=q.richDoc?reconcileEditorRich(q.richDoc,q.stem,p.next):null;
  if(q.richDoc&&!rich)throw Error('Chưa thể giữ định dạng của câu. Mở lại đề rồi chọn đoạn cần sửa.');
  change('Sửa vùng chọn của câu '+(e.questions.indexOf(q)+1),()=>{
   q.stem=p.next;
   if(rich)q.richDoc=rich;
   q.runs=null;
   if(q.rule&&!q.rule.startsWith('math-')){q.dataLinked=true;q.rule=null;}
   touch(q);check(exam(),q);
  });
  selection=null;pending=null;dialog.close();break;
 }
 case 'data':showData();break;
 case 'apply-data':{const p=pending;flushEditor();if(p?.type!=='data'||p.examId!==e.id||p.revision!==e.revision)return toast('Dữ liệu đề đã đổi. Vui lòng xem lại ảnh hưởng.');change('Cập nhật dữ kiện, bảng, biểu đồ & trạng thái câu',e=>Object.assign(e,p.update));pending=null;n.disabled=true;try{await saveChain;dialog.close();}catch(error){toast('Chưa đồng bộ dữ kiện. '+error.message);}break;}
 case 'check-one':runCheck(n.dataset.id||selected);break;
 case 'check-all':change('Rà soát toàn đề',e=>e.questions.forEach(q=>check(e,q)));modal('Kết quả rà soát',`<p class="hint">Kiểm tra cấu trúc và phép tính của câu có liên kết bảng. Đây là rà soát tại máy; dùng nút giải lại bằng AI trong trợ lý để kiểm tra nội dung.</p>${e.questions.map((q,i)=>`<div class="small-card"><b>Câu ${i+1} · ${statusText(q)}</b><p>${esc(q.check.problems.join(' ')||q.check.evidence)}</p>${button('review','Xem căn cứ','',`data-id="${q.id}"`)}</div>`).join('')}`);break;
 case 'review':showReview(n.dataset.id||selected);break;
 case 'repair-preview':showRepair(n.dataset.id);break;
 case 'apply-repair':{const p=pending,q=qget(p?.id);if(p?.type!=='repair'||!q||q.v!==p.version)return toast('Đề xuất đã cũ. Kiểm tra lại bản hiện tại.');change('Sửa đáp án & kiểm tra lại câu '+(e.questions.indexOf(q)+1),()=>{q.answer=p.answer;q.answerKnown=true;q.options=p.options;q.explanation=p.explanation;touch(q);check(e,q);});pending=null;showReview(q.id);break;}
 case 'approve-question':{const q=qget(n.dataset.id);if(!q||n.dataset.version&&q.v!==Number(n.dataset.version))throw Error('Câu đã đổi phiên bản; mở lại để duyệt.');change('Giáo viên duyệt câu '+(e.questions.indexOf(q)+1),()=>{approveQuestion(q);});dialog.close();break;}
 case 'undo':if(undo(e)){selection=null;persist().catch(()=>{});render();toast('Đã hoàn tác cả phần liên quan');}break;
 case 'redo':if(redo(e)){selection=null;persist().catch(()=>{});render();toast('Đã làm lại thay đổi');}break;
 case 'source':await showSource(n.dataset.doc,n.dataset.id);break;
 case 'import-doc':showImport();break;
 case 'download-original':{const d=e.docs.find(d=>d.id===n.dataset.doc),url=await db.get('file:'+d.fileId);const link=document.createElement('a');link.href=url;link.download=d.name;link.click();break;}
 case 'memory':showMemory();break;
 case 'delete-pref':state.prefs=state.prefs.filter(p=>p.id!==n.dataset.id);persist();render();showMemory();break;
 case 'edit-pref':{const p=state.prefs.find(p=>p.id===n.dataset.id);modal('Xem và xác nhận yêu cầu',`<form id="pref-edit-form" data-id="${p.id}"><label>Nội dung yêu cầu</label><textarea name="text" rows="4" required maxlength="500">${esc(p.text)}</textarea><p class="hint">Áp dụng cho các đề tạo sau. Nội dung trong đề đã tạo được giữ cho tới khi thầy cô chủ động áp dụng lại.</p>${foot('<button type="submit" class="primary">Xác nhận yêu cầu mới</button>')}</form>`);break;}
 case 'apply-prefs-current':change('Áp dụng yêu cầu đã xác nhận',e=>{e.appliedPrefs=clone(state.prefs.filter(isConfirmedPreference));e.questions.forEach(q=>check(e,q));});showMemory();break;
 case 'quotes':showQuotes();break;
 case 'add-variant':showAddVariant();break;
 case 'web-search':modal('Tìm các bản trên web','<div class="alert">Chưa bật tìm nguồn trên web trong app. Chưa có truy vấn nào được gửi hoặc kết quả nào được tìm.</div><p class="hint">Thầy cô có thể tự tra cứu và dán bản tìm được kèm địa chỉ nguồn để đối chiếu ngay tại máy. Khi nối dịch vụ tìm kiếm, kết quả cần có URL, vị trí và nội dung truy cập được; không tự dùng làm ngữ liệu trước khi thầy cô chọn.</p>'+foot(button('add-variant','Nhập bản đã tìm được','primary')));break;
 case 'choose-variant':{
  const v=e.quote.versions.find(v=>v.id===n.dataset.id);
  if(!v)return toast('Bản ngữ liệu đã đổi. Mở lại danh sách để chọn.');
  pending={type:'quote',examId:e.id,id:v.id,revision:e.revision};
  modal('Chọn bản ngữ liệu dùng trong đề',`<div class="diff"><del>${esc(e.quote.text)}</del><ins>${diffText(e.quote.text,v.text)}</ins></div><p class="hint">Cập nhật ngữ liệu và đánh dấu các câu đọc hiểu liên quan cần kiểm tra lại. Không đổi phương án hoặc tự kết luận dị bản nào sai.</p>${foot(button('apply-quote','Xác nhận bản dùng','primary'))}`);
  break;
 }
 case 'apply-quote':{
  const p=pending;
  if(p?.type!=='quote'||p.examId!==e.id||p.revision!==e.revision)return toast('Đề đã thay đổi, chọn lại bản.');
  const v=e.quote.versions.find(v=>v.id===p.id);
  if(!v)return toast('Bản ngữ liệu đã đổi. Mở lại danh sách để chọn.');
  const page=v.docId&&Number.isInteger(v.page)&&v.page>0?v.page:null;
  change('Giáo viên chọn bản ngữ liệu',e=>{
   e.quote.text=v.text;
   e.quote.chosen=v.id;
   e.questions.filter(q=>q.quote).forEach(q=>{
    touch(q);
    q.source={docId:v.docId||null,location:v.location||v.url||'Bản nhập tay',...(page?{page}:{})};
    check(e,q);
   });
  });
  pending=null;
  showQuotes();
  break;
 }
 case 'history':showHistory();break;
 case 'restore':{const h=e.history.find(h=>h.id===n.dataset.id);pending={type:'restore',id:h.id};modal('Xem bản đề '+h.revision,`<h3>${esc(h.state.title)}</h3><p class="hint">${esc(h.label)} · ${date(h.at)}</p>${h.state.questions.map((q,i)=>`<div class="small-card"><b>Câu ${i+1} · v${q.v}</b><div class="read-formula">${richTextHTML(q.stem)}</div></div>`).join('')}${foot(button('apply-restore','Khôi phục bản này','primary'))}`);break;}
 case 'apply-restore':{const h=e.history.find(h=>h.id===pending?.id);if(!h)return;change('Khôi phục bản đề '+h.revision,e=>Object.assign(e,clone(h.state)));selection=null;pending=null;dialog.close();break;}
 case 'export':showExport();break;
 case 'export-html':{const t=n.dataset.teacher==='true';download(safeName(e.title)+(t?' — Giao-vien':' — Hoc-sinh')+'.html',exportHTML(e,t),'text/html;charset=utf-8');break;}
 case 'print':{const win=window.open('about:blank','_blank');if(!win)return toast('Cho phép mở cửa sổ để xem bản in.');win.document.write(exportHTML(e,n.dataset.teacher==='true'));win.document.close();break;}
 case 'backup':await backup();break;
 case 'backup-local':await backup(true);break;
 case 'save-local':await saveLocal({type:'exam',exam:e,teacher:n.dataset.teacher==='true'});break;
 case 'import-backup':
  chooseFile('.json',async file=>{
   if(file.size>150*1024*1024)throw Error('Bản sao quá lớn.');
   const content=await file.text();
   let backup;
   try{backup=JSON.parse(content);}
   catch{throw Error('Tệp JSON bị hỏng. Hãy chọn bản sao tải từ ứng dụng.');}
   await saveChain;
   const preview=await db.previewRestore(backup);
   pending={type:'backup',data:backup,revision:preview.revision};
   modal('Khôi phục bản sao dữ liệu',`<p>Đã kiểm bản sao: ${preview.exams} đề, ${preview.files} tệp và ${preview.prefs} yêu cầu đã xác nhận.</p>${preview.curriculumSources?`<p>Có ${preview.curriculumSources} học liệu cá nhân. Học liệu mới trong kho đích cần được xác nhận lại quyền trước khi dùng cho AI.</p>`:''}${preview.matrixTemplates?`<p>Có ${preview.matrixTemplates} mẫu ma trận cá nhân.</p>`:''}<div class="alert">Thay các đề trong tài khoản hiện tại bằng bản sao này, gồm lịch sử và hoàn tác. Hãy tải bản sao hiện tại nếu cần giữ lại. Khóa AI, tài khoản, liên kết chia sẻ và tác vụ AI cũ không được khôi phục từ JSON.</div>${foot(button('backup','Tải bản sao hiện tại')+button('confirm-backup','Khôi phục kho này','primary'))}`);
  });
  break;
 case 'confirm-backup':{
  const backup=pending;
  if(backup?.type!=='backup'||n.disabled)return;
  n.disabled=true;
  try{
   await saveChain;
   if(pending!==backup||!n.isConnected||!dialog.open)return;
   const result=await db.restoreBackup(backup.data,backup.revision);
   pending=null;
   dialog.close();
   if(result.cacheWarning)toast(result.cacheWarning);
   location.reload();
  }finally{if(n.isConnected)n.disabled=false;}
  break;
 }
 case 'connections':showConnections();break;
 case 'extract':await showExtract();break;
 default:break;
 }}
document.addEventListener('click',async event=>{const n=event.target.closest('[data-action]');if(!n)return;event.preventDefault();try{await handleAction(n.dataset.action,n);}catch(err){console.error(err);toast(friendlyClientMessage(err));if(dialog.open&&dialog.querySelector('.busy'))modal('Chưa thực hiện được',`<div class="alert">${esc(friendlyClientMessage(err))}</div><p class="hint">Chưa áp dụng thay đổi. Có thể điều chỉnh kết nối hoặc thử lại.</p>`);}});
document.addEventListener('input',event=>{const n=event.target;if(n.matches('textarea.stem'))autosize();if(n.dataset.qField||n.dataset.examField){document.querySelectorAll('[data-save-status]').forEach(el=>el.textContent='Đang soạn…');clearTimeout(inlineTimer);inlineTimer=setTimeout(()=>n.dispatchEvent(new Event('change',{bubbles:true})),450);}});
document.addEventListener('change',async event=>{const n=event.target;try{if(n.dataset.qField||n.dataset.examField)clearTimeout(inlineTimer);if(n.dataset.examField){const f=n.dataset.examField;if(n.value!==exam()[f])change('Sửa '+(f==='title'?'tên đề':'hướng dẫn'),e=>{e[f]=n.value;},{renderPage:false});if($('.breadcrumb b'))$('.breadcrumb b').textContent=exam().title;if($('.header-title'))$('.header-title').textContent=exam().title;}if(n.dataset.examField==='title')document.querySelectorAll('[data-exam-field="title"]').forEach(other=>{if(other!==n)other.value=exam().title;});if(n.dataset.qField){const q=qget(n.dataset.id),f=n.dataset.qField;const value=f==='answer'?Number(n.value):f==='truthValue'?(n.value===''?null:n.value==='true'):n.value;const equal=f==='option'?q.options[Number(n.dataset.index)]===value:f==='truthValue'?q.truthValues?.[Number(n.dataset.index)]===value:q[f]===value;if(equal&&(!['answer','answerText','truthValue'].includes(f)||q.answerKnown!==false))return;change('Sửa '+(f==='stem'?'thân câu':f==='option'?'phương án':f==='answer'?'đáp án':'giải thích')+' câu '+(exam().questions.indexOf(q)+1),()=>{if(f==='option')q.options[Number(n.dataset.index)]=value;else if(f==='truthValue'){if(!Array.isArray(q.truthValues)||q.truthValues.length!==4||(q.answerKnown===false&&q.truthValues.every(x=>typeof x==='boolean')))q.truthValues=[null,null,null,null];q.truthValues[Number(n.dataset.index)]=value;q.answerKnown=q.truthValues.every(x=>typeof x==='boolean');}else q[f]=value;if(f==='answer')q.answerKnown=n.value!=='';if(f==='answerText')q.answerKnown=!!value.trim();if(f==='stem'&&q.rule&&!q.rule.startsWith('math-')){q.dataLinked=true;q.rule=null;}touch(q);check(exam(),q);},{renderPage:false});selection=null;setTimeout(()=>{if(!dialog.open)refreshInline();},500);}if(n.id==='doc-file'&&n.files[0])await importFile(n.files[0]);if(n.id==='scan-doc')await showExtract(n.value);}catch(err){toast(err.message);}});
function captureSelection(event){const n=event.target;if(!n.matches('textarea.stem'))return;const q=qget(n.dataset.id);if(!q)return;const start=n.selectionStart,end=n.selectionEnd;if(start===end)return;selected=q.id;selection={id:q.id,version:q.v,field:'stem',start,end,text:n.value.slice(start,end)};$('.assistant-body').innerHTML=rightHTML();refreshReferenceScope(mvpContext);refreshWorkbench();document.querySelectorAll('.question').forEach(el=>el.classList.toggle('selected',el.dataset.q===selected));document.querySelectorAll('.outline-item').forEach(el=>el.classList.toggle('active',el.dataset.id===selected));}
document.addEventListener('mouseup',captureSelection);document.addEventListener('keyup',captureSelection);
document.addEventListener('submit',async event=>{event.preventDefault();const f=event.target,e=exam();try{if(handleStudioSubmit(f))return;if(await handleWorkbenchSubmit(f))return;if(await handleMVPSubmit(f))return;if(f.id==='chat-form'){const text=$('#chat-input').value.trim();if(!text)return;addChat('user',text);if(/^đổi thành\s*:/i.test(text)){const s=currentScope();if(!s){addChat('assistant','Chọn một câu trước khi thay nội dung.');render();return;}pending={...s,type:'replace'};previewReplace(text.replace(/^đổi thành\s*:\s*/i,''));render();}else if(/^kiểm tra/i.test(text)&&selected){runCheck(selected);}else{addChat('assistant','Chưa kết nối AI nên tôi chưa thể thực hiện yêu cầu tự do này. Thầy cô có thể chọn chữ và bấm “Sửa phần đã chọn”, hoặc nhập “Đổi thành: …” để xem trước thay đổi. Các nút kiểm tra, dữ kiện và đối chiếu đang hoạt động tại máy.');render();}return;}
 if(f.id==='matrix-form'){const rows=readMatrixFormRows(f);const confirmed=$('#matrix-confirm').checked;change('Cập nhật ma trận'+(confirmed?' đã xác nhận':''),e=>{e.matrix=rows;e.matrixConfirmed=confirmed;});dialog.close();tab='matrix';render();return;}
 if(f.id==='meta-form'){const v=Object.fromEntries(new FormData(f));v.minutes=Number(v.minutes);change('Sửa thông tin đề',e=>Object.assign(e,v));dialog.close();return;}
 if(f.id==='q-meta-form'){const q=qget(f.dataset.id),v=Object.fromEntries(new FormData(f));change('Cập nhật thuộc tính câu '+(e.questions.indexOf(q)+1),()=>{q.topic=v.topic.trim();q.level=Number(v.level);q.points=Number(v.points);const changedType=q.type!==v.type;q.type=v.type;if(['essay','short'].includes(q.type)){q.options=[];q.rule=null;}else if(q.options.length!==4)q.options=['','','',''];q.source=v.docId?{docId:v.docId,location:v.location}:null;if(q.type==='mcq'&&v.answer!==undefined&&v.answer!==''){q.answer=Number(v.answer);q.answerKnown=true;}if(changedType)q.answerKnown=false;q.explanation=v.explanation;touch(q);check(e,q);});dialog.close();return;}
 if(f.id==='data-form'){flushEditor();if(f.dataset.exam!==e.id||Number(f.dataset.revision)!==e.revision)throw Error('Dữ liệu đề đã đổi. Mở lại Sửa dữ kiện.');showDataPreview([...f.querySelectorAll('[data-data-index]')].map(input=>input.valueAsNumber));return;}
 if(f.id==='paste-doc-form'){const v=Object.fromEntries(new FormData(f)),d={id:uid(),name:v.name.trim(),text:v.text,kind:'text',sample:false};change('Thêm tư liệu nhập tay',e=>e.docs.push(d));tab='docs';render();await showSource(d.id);return;}
 if(f.id==='pref-form'){if(!$('#pref-confirm').checked)throw Error('Xác nhận yêu cầu trước khi ghi nhớ.');const text=$('#pref-text').value.trim();if(!text)throw Error('Nhập yêu cầu trước khi xác nhận.');state.prefs.push({id:uid(),text,kind:$('#pref-kind').value,maxWords:30,confirmedAt:Date.now()});persist();render();showMemory();return;}
 if(f.id==='pref-edit-form'){const p=state.prefs.find(p=>p.id===f.dataset.id);p.text=new FormData(f).get('text').trim();p.confirmedAt=Date.now();persist();showMemory();return;}
 if(f.id==='variant-form'){const v=Object.fromEntries(new FormData(f));if(v.url&&!/^https?:\/\//i.test(v.url))throw Error('Nguồn cần dùng địa chỉ http hoặc https.');const variant={...v,id:uid(),external:true};change('Thêm bản đối chiếu nhập tay',e=>e.quote.versions.push(variant));showQuotes();return;}
 if(f.id==='scan-form'){const text=new FormData(f).get('text'),doc=e.docs.find(d=>d.id===f.dataset.doc);if(!doc)throw Error('Thêm bản gốc trước khi lưu bản đối chiếu.');change('Lưu văn bản nhập tay từ bản gốc',e=>{doc.manualText=text;const existing=e.docs.find(d=>d.originalId===doc.id);if(existing)existing.text=text;else e.docs.push({id:uid(),name:'Bản nhập tay — '+doc.name,kind:'text',text,originalId:doc.id,sample:false});});toast('Đã lưu bản nhập tay · chưa có nhận dạng tự động');await showExtract(doc.id);}
 }catch(err){console.error(err);toast(err.message);if(dialog.open&&dialog.querySelector('.busy'))modal('Chưa thực hiện được',`<div class="alert">${esc(friendlyClientMessage(err))}</div><p class="hint">Chưa áp dụng thay đổi. Kiểm tra kết nối hoặc dữ liệu đầu vào.</p>`);}});
dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});
dialog.addEventListener('close',()=>{const el=modalReturnFocus;modalReturnFocus=null;if(el?.isConnected)el.focus();});
window.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key==='s'&&!event.isComposing){event.preventDefault();if(!flushEditor())return;document.activeElement?.blur();persist().then(()=>toast('Đã lưu đề trên máy')).catch(err=>toast(friendlyClientMessage(err)));}});
async function init(){try{await bootstrapWorkbench();state=await db.get('state');showSaveWarning(db.hasPendingWrites());if(!state){const e=sample();e.questions.forEach(q=>check(e,q));state={version:1,current:e.id,exams:[e],prefs:[]};await persist();}if(new URLSearchParams(location.search).get('demo')==='toan'){let target=state.exams.find(e=>e.subject==='Toán'&&e.sample);if(!target){target=sample('Toán',state.prefs);target.questions.forEach(q=>check(target,q));state.exams.push(target);}state.current=target.id;await persist();history.replaceState({},'',location.pathname);}render();await initMVP(mvpContext);await initWorkbench(mvpContext);}catch(err){app.innerHTML=`<div style="padding:40px"><h1>Chưa mở được dữ liệu tại máy</h1><p>${esc(friendlyClientMessage(err))}</p><p>Mở app trong cửa sổ trình duyệt thông thường có hỗ trợ IndexedDB.</p></div>`;}}
init();
